mapper.select:
SELECT id,revision,inherit_personal FROM pf.capability_binding_set
WHERE space_id=#{actor.spaceId} AND owner_user_id=#{actor.userId}
  AND workspace_id IS NOT DISTINCT FROM #{workspaceId,jdbcType=OTHER}

SELECT capability_id,version_id FROM pf.capability_binding_selection
WHERE space_id=#{actor.spaceId} AND owner_user_id=#{actor.userId} AND binding_set_id=#{setId}
ORDER BY capability_id
